//! Opt-in PALS Repair/recheck without creating a researcher.
//!
//! These are continuations over actual submitted P/C questions. The original
//! mixed linear lane is independent. A proposal is generated by P, a distinct
//! counter by C, a repair AFTER that exact response by P, and an independent
//! response to the changed repair by C. No unaccepted suffix is spliced in.
use super::*;
use crate::pals::coordinator::AcceptedPeerSourceSeal;
use crate::pals::value::ModelValueIdentity;

#[path = "repair_followup.rs"]
mod repair_followup;

const MAX_CYCLES: usize = super::super::frozen_recheck::MAX_PENDING_REPAIRS;
const MAX_PER_FIRST: u8 = super::super::frozen_recheck::MAX_REPAIRS_PER_FIRST;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PcRepairPhase {
    Proposal,
    AttackRanking,
    CounterStart,
    CounterTail,
    VisibleCounterReview,
    Repair,
    RecheckStart,
    RecheckTail,
    FreezePair,
    FreshRepair,
    FreshCounter,
}

pub(super) struct PcRepairOrigin {
    owner: Arc<()>,
    authority: SearchAuthority,
    deadline: Deadline,
    root_budget: ContractDigest,
    first: BoardMove,
    frame: u64,
    end: usize,
    model: ModelValueIdentity,
    initial_source: AcceptedPeerSourceSeal,
}

/// New invocations borrow this immutable recipe. It owns no worker, TT, native
/// credit, manufactured completion or unobserved model result.
#[derive(Clone)]
pub(super) struct PcRepairStep {
    origin: Arc<PcRepairOrigin>,
    cycle: u64,
    parent_cycle: Option<u64>,
    phase: PcRepairPhase,
    prefix: Vec<BoardMove>,
    proposal: Vec<BoardMove>,
    counter: Option<Vec<BoardMove>>,
    repaired: Option<Vec<BoardMove>>,
    attack: Option<usize>,
    divergences: Vec<usize>,
    excluded: Option<BoardMove>,
    frozen: Option<Arc<ReviewView>>,
    frozen_context: Option<RoleLogicalContext>,
    pub(super) responsibilities: Vec<PcResponsibilitySource>,
}

/// Test-only scalar observation. It grants no live question or acceptance
/// authority and is absent from production builds.
#[cfg(test)]
pub(super) struct PcRepairFixtureScope {
    pub(super) cycle: u64,
    pub(super) parent_cycle: Option<u64>,
    pub(super) phase: PcRepairPhase,
    pub(super) authority: SearchAuthority,
    pub(super) deadline: Deadline,
    pub(super) root_budget: ContractDigest,
    pub(super) first: BoardMove,
    pub(super) frame: u64,
    pub(super) end: usize,
}

#[derive(Clone, Copy)]
pub(super) struct PublishedPcLine {
    pub(super) line: LineId,
    pub(super) observation: ObservationId,
    pub(super) revision: u64,
    pub(super) kind: RecordKind,
}

#[derive(Clone, Copy)]
pub(super) struct PcLineRelations {
    pub(super) parent: Option<PublishedPcLine>,
    pub(super) supersedes: Option<PublishedPcLine>,
}

/// Mutable cycle facts are single-writer port state. Every stored head came
/// from the port's actual one-use AcceptedRoleStep consumption boundary.
pub(super) struct CycleFacts {
    pub(super) phase: PcRepairPhase,
    pub(super) stopped_reason: Option<&'static str>,
    pub(super) progress: super::repair_report::PcRepairProgress,
    pub(super) last_accepted: Option<AcceptedPeerSourceSeal>,
    pub(super) proposal: Option<PublishedPcLine>,
    pub(super) counter: Option<PublishedPcLine>,
    pub(super) previous_repair: Option<PublishedPcLine>,
    pub(super) target: Option<Arc<super::repair_witness::PcDivergenceSource>>,
    pub(super) attack_source: Option<Arc<PcAttackRankedSource>>,
    pub(super) repair: Option<Arc<super::repair_witness::PcRepairAcceptedLine>>,
    pub(super) recheck: Option<Arc<super::repair_witness::PcRepairAcceptedLine>>,
    pub(super) recheck_publication: Option<PublishedPcLine>,
    pub(super) followup: Option<PcRepairStep>,
    pub(super) repair_endpoint: Option<super::repair_witness::PcAcceptedFreshEndpoint>,
    pub(super) counter_endpoint: Option<super::repair_witness::PcAcceptedFreshEndpoint>,
}

pub(super) struct PcRepairCycles {
    pub(super) policy: PostRepairRecheckPolicy,
    pub(super) root_budget: ContractDigest,
    pub(super) next_cycle: u64,
    pub(super) next_event: u64,
    pub(super) per_first: HashMap<BoardMove, u8>,
    pub(super) active: HashMap<u64, CycleFacts>,
    pub(super) witnesses: VecDeque<super::repair_witness::PcDivergenceWitness>,
}
impl PcRepairCycles {
    pub(super) fn new(
        policy: PostRepairRecheckPolicy,
        root_budget: ContractDigest,
    ) -> Result<Self, PalsError> {
        if policy != PostRepairRecheckPolicy::IterativeFrozenModelWdlV2 {
            return Err(PalsError::InvalidConfig);
        }
        Ok(Self {
            policy,
            root_budget,
            next_cycle: 1,
            next_event: 1,
            per_first: HashMap::new(),
            active: HashMap::new(),
            witnesses: VecDeque::new(),
        })
    }
}

impl super::repair_report::PcRepairProgress {
    pub(super) fn capture(step: &PcRepairStep) -> Self {
        Self {
            cycle: step.cycle,
            parent_cycle: step.parent_cycle,
            phase: step.phase,
            first: step.origin.first,
            model: step.origin.model.clone(),
            root_source: step.origin.initial_source,
            prefix: step.prefix.clone(),
            proposal: step.proposal.clone(),
            counter: step.counter.clone(),
            repaired: step.repaired.clone(),
        }
    }
}
impl PcRepairStep {
    #[cfg(test)]
    pub(super) fn fixture_scope(&self) -> PcRepairFixtureScope {
        PcRepairFixtureScope {
            cycle: self.cycle,
            parent_cycle: self.parent_cycle,
            phase: self.phase,
            authority: self.origin.authority,
            deadline: self.origin.deadline,
            root_budget: self.origin.root_budget,
            first: self.origin.first,
            frame: self.origin.frame,
            end: self.origin.end,
        }
    }
    pub(super) fn owned_host_bytes(&self) -> Option<u64> {
        use super::repair_report::{line_bytes, model_bytes, optional_line_bytes};
        let mut bytes = u64::try_from(std::mem::size_of::<Self>())
            .ok()?
            .checked_add(u64::try_from(std::mem::size_of::<PcRepairOrigin>()).ok()?)?
            .checked_add(model_bytes(&self.origin.model)?)?
            .checked_add(line_bytes(&self.prefix)?)?
            .checked_add(line_bytes(&self.proposal)?)?
            .checked_add(optional_line_bytes(&self.counter)?)?
            .checked_add(optional_line_bytes(&self.repaired)?)?
            .checked_add(
                u64::try_from(
                    self.divergences
                        .capacity()
                        .checked_mul(std::mem::size_of::<usize>())?,
                )
                .ok()?,
            )?
            .checked_add(
                u64::try_from(
                    self.responsibilities
                        .capacity()
                        .checked_mul(std::mem::size_of::<PcResponsibilitySource>())?,
                )
                .ok()?,
            )?;
        for duty in &self.responsibilities {
            bytes = bytes
                .checked_add(line_bytes(&duty.prefix)?)?
                .checked_add(u64::try_from(duty.parent.retained_history_bytes()?).ok()?)?
                .checked_add(u64::try_from(duty.snapshot.retained_history_bytes()?).ok()?)?
                .checked_add(duty.source.owned_host_bytes()?)?;
        }
        if let Some(context) = &self.frozen_context {
            bytes = bytes.checked_add(line_bytes(&context.prefix)?)?;
        }
        // The actual native prepared owner separately accounts the shared
        // selected View. This scalar recipe does not duplicate its tensors.
        Some(bytes)
    }
    pub(super) fn is_initial_attack_ranking(&self) -> bool {
        self.phase == PcRepairPhase::AttackRanking && self.counter.is_none()
    }
    pub(super) fn divergences(&self) -> &[usize] {
        &self.divergences
    }
    pub(super) fn first(&self) -> BoardMove {
        self.origin.first
    }
    pub(super) fn frozen(&self) -> Option<&Arc<ReviewView>> {
        self.frozen.as_ref()
    }
    pub(super) fn frozen_context(&self) -> Option<&RoleLogicalContext> {
        self.frozen_context.as_ref()
    }
    pub(super) fn is_recipe(&self) -> bool {
        self.phase == PcRepairPhase::FreezePair
    }
    pub(super) fn digest(&self) -> Result<ContractDigest, PalsError> {
        let mut hash = Sha256::new();
        hash.update(b"rz-rovent-pc-pals-repair-recheck-question/1\0");
        hash.update(self.cycle.to_le_bytes());
        hash.update([u8::from(self.parent_cycle.is_some())]);
        if let Some(parent) = self.parent_cycle {
            hash.update(parent.to_le_bytes());
        }
        hash.update([self.phase as u8]);
        hash.update(self.origin.root_budget.0);
        hash.update(self.origin.initial_source.origin().seal_digest().0);
        hash.update(role_line_sha256(b"cycle-prefix", &self.prefix)?);
        hash.update(role_line_sha256(b"cycle-proposal", &self.proposal)?);
        for line in [&self.counter, &self.repaired] {
            hash.update([u8::from(line.is_some())]);
            if let Some(line) = line {
                hash.update(role_line_sha256(b"cycle-line", line)?);
            }
        }
        for ply in &self.divergences {
            hash.update((*ply as u64).to_le_bytes());
        }
        hash.update((self.attack.unwrap_or(usize::MAX) as u64).to_le_bytes());
        Ok(ContractDigest(hash.finalize().into()))
    }

    pub(super) fn validates(
        &self,
        input: &FrameInput<ReviewView, PcPortQuestion>,
        owner: &Arc<()>,
        authority: SearchAuthority,
        budget: Option<ContractDigest>,
    ) -> Result<(), PalsError> {
        if !Arc::ptr_eq(&self.origin.owner, owner)
            || self.origin.authority != authority
            || self.origin.deadline != input.question.source.original_deadline
            || Some(self.origin.root_budget) != budget
            || self.origin.frame != input.question.frame
            || self.origin.first != input.question.first.ok_or(RoleError::InvalidOutput)?
            || self.prefix != input.question.context.prefix
            || self.proposal != input.view.query().proposal
            || self.counter != input.view.query().counterexample
            || self.divergences != input.view.query().divergences
            || self.is_recipe()
            || input.question.goal_local.is_some()
        {
            return Err(RoleError::InvalidOutput.into());
        }
        Ok(())
    }
}

impl<M: RoleModel> PcSemanticPort<M> {
    /// This selects the already existing PALS policy; no new evaluator or
    /// implicit policy is installed. Call before the first root role input.
    pub fn enable_post_repair_recheck(
        &mut self,
        policy: PostRepairRecheckPolicy,
    ) -> Result<(), PalsError> {
        if self.next_question != 1
            || !self.pending.is_empty()
            || self.repair_cycles.is_some()
            || self.post_repair_recheck != PostRepairRecheckPolicy::Disabled
        {
            return Err(PalsError::InvalidConfig);
        }
        if policy == PostRepairRecheckPolicy::Disabled {
            return Ok(());
        }
        let budget = self
            .original_root_budget()
            .ok_or(PalsError::InvalidConfig)?;
        self.repair_cycles = Some(PcRepairCycles::new(policy, budget)?);
        self.post_repair_recheck = policy;
        Ok(())
    }

    pub fn post_repair_recheck(&self) -> PostRepairRecheckPolicy {
        self.post_repair_recheck
    }

    pub fn divergence_witnesses(
        &self,
    ) -> impl Iterator<Item = &super::repair_witness::PcDivergenceWitness> {
        self.repair_cycles
            .iter()
            .flat_map(|cycles| cycles.witnesses.iter())
    }

    // The original input, accepted head/output, Rules child and responsibility
    // lineage remain separate checked sources at Repair admission.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn enqueue_actual_repair_cycle(
        &mut self,
        input: &FrameInput<ReviewView, PcPortQuestion>,
        accepted: &AcceptedRoleStep,
        output: &RoleOutput,
        node: usize,
        prefix: &[BoardMove],
        frame: u64,
        responsibilities: &[PcResponsibilitySource],
    ) -> Result<(), PalsError> {
        if self.repair_cycles.is_none() {
            return Ok(());
        }
        // An optional Repair cycle shares the original go horizon. Its
        // generation chunk cannot authorize a child beyond that horizon,
        // and fewer than three plies cannot form this Repair recipe.
        let end = self.owner.config.line_plies.min(self.continuation_limit());
        let root_budget = self
            .original_root_budget()
            .ok_or(PalsError::InvalidConfig)?;
        let Some(cycles) = &mut self.repair_cycles else {
            return Ok(());
        };
        if input.question.context.purpose != RoleQueryPurpose::ProposePolicy
            || !input.question.context.prefix.is_empty()
            || prefix.len() != 1
            || end < 3
            || self.owner.semantic.nodes[node].terminal.is_some()
        {
            return Ok(());
        }
        let first = prefix[0];
        let count = cycles.per_first.entry(first).or_default();
        if *count >= MAX_PER_FIRST {
            return Ok(());
        }
        if cycles.active.len() >= MAX_CYCLES || self.ready.len() >= MAX_PC_PENDING {
            return Err(PalsError::Capacity);
        }
        let id = cycles.next_cycle;
        let next = id.checked_add(1).ok_or(PalsError::Capacity)?;
        let origin = accepted
            .origin(
                input.question.frontier_frame(),
                input.question.reciprocal_question(),
            )
            .map_err(|_| RoleError::InvalidOutput)?;
        let source = AcceptedPeerSourceSeal::freeze(origin, &input.view, output)
            .map_err(|_| RoleError::InvalidOutput)?;
        let origin = Arc::new(PcRepairOrigin {
            owner: Arc::clone(&self.identity),
            authority: self.authority,
            deadline: self.deadline,
            root_budget,
            first,
            frame,
            end,
            model: self
                .owner
                .model_value_identity()
                .ok_or(RoleError::Unavailable)?
                .clone(),
            initial_source: source,
        });
        let step = PcRepairStep {
            origin,
            cycle: id,
            parent_cycle: None,
            phase: PcRepairPhase::Proposal,
            prefix: prefix.to_vec(),
            proposal: prefix.to_vec(),
            counter: None,
            repaired: None,
            attack: None,
            divergences: Vec::new(),
            excluded: None,
            frozen: None,
            frozen_context: None,
            responsibilities: responsibilities.to_vec(),
        };
        cycles
            .active
            .try_reserve(1)
            .map_err(|_| PalsError::Capacity)?;
        self.ready.try_reserve(1).map_err(|_| PalsError::Capacity)?;
        cycles.active.insert(
            id,
            CycleFacts {
                phase: step.phase,
                stopped_reason: None,
                progress: super::repair_report::PcRepairProgress::capture(&step),
                last_accepted: None,
                proposal: None,
                counter: None,
                previous_repair: None,
                target: None,
                attack_source: None,
                repair: None,
                recheck: None,
                recheck_publication: None,
                followup: None,
                repair_endpoint: None,
                counter_endpoint: None,
            },
        );
        cycles.next_cycle = next;
        *count += 1;
        self.push_repair_plan(node, step, None)
    }

    fn push_repair_plan(
        &mut self,
        node: usize,
        step: PcRepairStep,
        peer: Option<PcPeerSource>,
    ) -> Result<(), PalsError> {
        if self.ready.len() >= MAX_PC_PENDING {
            return Err(PalsError::Capacity);
        }
        self.ready.try_reserve(1).map_err(|_| PalsError::Capacity)?;
        let purpose = match step.phase {
            PcRepairPhase::Proposal => RoleQueryPurpose::ProposePolicy,
            PcRepairPhase::AttackRanking | PcRepairPhase::VisibleCounterReview => {
                RoleQueryPurpose::DivergencePolicy
            }
            PcRepairPhase::CounterStart
            | PcRepairPhase::CounterTail
            | PcRepairPhase::RecheckStart
            | PcRepairPhase::RecheckTail => RoleQueryPurpose::ReplyPolicy,
            PcRepairPhase::Repair => RoleQueryPurpose::RepairPolicy,
            PcRepairPhase::FreezePair
            | PcRepairPhase::FreshRepair
            | PcRepairPhase::FreshCounter => RoleQueryPurpose::ValueFresh,
        };
        let phase = step.phase;
        let id = step.cycle;
        self.ready.push_back(PcPlan {
            node,
            frame: step.origin.frame,
            // A root inspection may temporarily precede the original
            // action anchor. Only actual ancestor duties belong to this Q;
            // the immutable step keeps every original duty for descendants.
            responsibilities: step
                .responsibilities
                .iter()
                .filter(|source| step.prefix.starts_with(source.prefix()))
                .cloned()
                .collect(),
            goal_local: None,
            peer_source: peer,
            continuation_end: step.origin.end,
            purpose,
            prefix: step.prefix.clone(),
            proposal: step.proposal.clone(),
            counter: step.counter.clone(),
            repair: Some(Arc::new(step)),
        });
        let facts = self
            .repair_cycles
            .as_mut()
            .ok_or(PalsError::InvalidConfig)?
            .active
            .get_mut(&id)
            .ok_or(RoleError::InvalidOutput)?;
        facts.phase = phase;
        facts.progress = super::repair_report::PcRepairProgress::capture(
            self.ready
                .back()
                .and_then(|plan| plan.repair.as_deref())
                .ok_or(RoleError::InvalidOutput)?,
        );
        Ok(())
    }

    fn repair_node(&self, prefix: &[BoardMove]) -> Result<usize, PalsError> {
        let mut node = self.root;
        for movement in prefix {
            node = self.owner.semantic.nodes[node]
                .edges
                .iter()
                .find(|edge| edge.movement == *movement)
                .ok_or(StoreError::InvalidHandle("actual Repair path edge"))?
                .child;
        }
        Ok(node)
    }

    fn repair_control(&self, step: &PcRepairStep) -> Result<(), PalsError> {
        if Instant::now() >= self.hard_deadline
            || step.origin.deadline != self.deadline
            || step.origin.authority != self.authority
            || !Arc::ptr_eq(&step.origin.owner, &self.identity)
            || self.original_root_budget() != Some(step.origin.root_budget)
            || self.owner.model_value_identity() != Some(&step.origin.model)
            || self
                .repair_cycles
                .as_ref()
                .and_then(|cycles| cycles.active.get(&step.cycle))
                .is_none_or(|facts| {
                    facts.stopped_reason.is_some()
                        || (facts.phase != step.phase
                            && !matches!(
                                (facts.phase, step.phase),
                                (
                                    PcRepairPhase::FreshRepair | PcRepairPhase::FreshCounter,
                                    PcRepairPhase::FreshRepair | PcRepairPhase::FreshCounter
                                )
                            ))
                })
        {
            return Err(RoleError::InvalidOutput.into());
        }
        Ok(())
    }

    /// Called only after the exact native acceptance passed the ordinary port
    /// ticket/output checks. Head consumption is charged before publication.
    pub(super) fn consume_repair_once(
        &mut self,
        input: &FrameInput<ReviewView, PcPortQuestion>,
        accepted: &AcceptedRoleStep,
        output: &RoleOutput,
        physical: Option<AdaptivePortRoleEvidence>,
    ) -> Result<(), PalsError> {
        let step = input
            .question
            .repair
            .as_ref()
            .ok_or(RoleError::InvalidOutput)?
            .as_ref()
            .clone();
        self.repair_control(&step)?;
        if step.is_recipe() {
            return Err(RoleError::InvalidOutput.into());
        }
        self.consume_pc_head_once(input, accepted, physical)?;
        let origin = accepted
            .origin(
                input.question.frontier_frame(),
                input.question.reciprocal_question(),
            )
            .map_err(|_| RoleError::InvalidOutput)?;
        let sealed = AcceptedPeerSourceSeal::freeze(origin, &input.view, output)
            .map_err(|_| RoleError::InvalidOutput)?;
        self.repair_cycles
            .as_mut()
            .and_then(|cycles| cycles.active.get_mut(&step.cycle))
            .ok_or(RoleError::InvalidOutput)?
            .last_accepted = Some(sealed);
        if matches!(
            step.phase,
            PcRepairPhase::FreshRepair | PcRepairPhase::FreshCounter
        ) {
            return self.consume_repair_endpoint(
                input,
                accepted,
                output,
                physical.ok_or(RoleError::InvalidOutput)?,
                &step,
            );
        }
        if matches!(
            step.phase,
            PcRepairPhase::AttackRanking | PcRepairPhase::VisibleCounterReview
        ) {
            let RolePayload::Counterexample {
                ref divergence_logits,
                ..
            } = output.payload
            else {
                return Err(RoleError::InvalidOutput.into());
            };
            let selected = divergence_logits
                .iter()
                .enumerate()
                .max_by(|(a, x), (b, y)| x.total_cmp(y).then_with(|| b.cmp(a)))
                .map(|(index, _)| index)
                .ok_or(RoleError::InvalidOutput)?;
            let attack = *step
                .divergences
                .get(selected)
                .ok_or(RoleError::InvalidOutput)?;
            let mut next = step.clone();
            next.attack = Some(attack);
            next.divergences.clear();
            if step.phase == PcRepairPhase::AttackRanking {
                let attack_source = PcAttackRankedSource::capture(
                    input,
                    accepted,
                    output,
                    selected,
                    &self.owner.semantic.stores,
                )?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&step.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .attack_source = Some(Arc::new(attack_source));
                next.phase = PcRepairPhase::CounterStart;
                next.prefix = next.proposal[..attack].to_vec();
                next.excluded = next.proposal.get(attack).copied();
            } else {
                let counter = next.counter.as_ref().ok_or(RoleError::InvalidOutput)?;
                let published = self
                    .repair_cycles
                    .as_ref()
                    .and_then(|cycles| cycles.active.get(&step.cycle))
                    .and_then(|facts| facts.counter)
                    .ok_or(RoleError::InvalidOutput)?;
                if published.kind != RecordKind::Counterexample {
                    return Err(RoleError::InvalidOutput.into());
                }
                let visible = input
                    .view
                    .records_metadata()
                    .iter()
                    .enumerate()
                    .find(|(index, metadata)| {
                        metadata.source_revision == published.revision
                            && input
                                .view
                                .records()
                                .get(*index)
                                .is_some_and(|record| record.kind == RecordKind::Counterexample)
                    })
                    .map(|(index, _)| index)
                    .ok_or(ReviewError::MissingRelation(published.revision))?;
                let source = super::repair_witness::PcDivergenceSource::capture(
                    input,
                    accepted,
                    output,
                    published.revision,
                    u16::try_from(visible).map_err(|_| PalsError::Capacity)?,
                    step.origin.first,
                    &self.owner.semantic.stores,
                )?;
                let initial = self
                    .repair_cycles
                    .as_ref()
                    .and_then(|cycles| cycles.active.get(&step.cycle))
                    .and_then(|facts| facts.attack_source.as_ref())
                    .map(Arc::clone);
                let source = source.with_attack_ranked_source(initial)?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&step.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .target = Some(Arc::new(source));
                next.phase = PcRepairPhase::Repair;
                // PALS repairs after the exact selected C response. The
                // original attack move and original first move remain fixed.
                next.prefix = counter[..=attack].to_vec();
                next.excluded = None;
            }
            let node = self.repair_node(&next.prefix)?;
            return self.push_repair_plan(
                node,
                next,
                Some(PcPeerSource::freeze(input, accepted, output)?),
            );
        }
        let ranked = rank_moves(&input.view.query().legal, output)?;
        let Some(movement) = ranked
            .into_iter()
            .find(|movement| Some(*movement) != step.excluded)
        else {
            return self
                .finish_repair_unknown(step.cycle, "no distinct completed policy alternative");
        };
        let Some(admitted) = self.admit_selected_child(input, accepted, output, movement)? else {
            return Ok(());
        };
        let child = admitted.node;
        let mut next = step.clone();
        next.prefix.push(movement);
        next.excluded = None;
        match next.phase {
            PcRepairPhase::CounterStart => next.phase = PcRepairPhase::CounterTail,
            PcRepairPhase::RecheckStart => next.phase = PcRepairPhase::RecheckTail,
            _ => {}
        }
        let duty = match step.phase {
            PcRepairPhase::CounterStart | PcRepairPhase::RecheckStart => {
                Some(FrontierFrameKind::Counter)
            }
            PcRepairPhase::Repair
                if step.prefix.len() == step.attack.ok_or(RoleError::InvalidOutput)? + 1 =>
            {
                Some(FrontierFrameKind::Repair)
            }
            _ => None,
        };
        if let Some(kind) = duty {
            next.responsibilities
                .push(PcResponsibilitySource::from_selection(
                    kind,
                    input,
                    accepted,
                    movement,
                    &self.owner.semantic.nodes[child].position,
                    next.prefix.clone(),
                )?);
        }
        let terminal = self.owner.semantic.nodes[child].terminal.is_some();
        if !terminal && next.prefix.len() < next.origin.end {
            if next.phase == PcRepairPhase::Proposal {
                next.proposal = next.prefix.clone();
            }
            return self.push_repair_plan(
                child,
                next,
                Some(PcPeerSource::freeze(input, accepted, output)?),
            );
        }
        self.complete_repair_tail(input, accepted, output, child, next)
    }

    fn complete_repair_tail(
        &mut self,
        input: &FrameInput<ReviewView, PcPortQuestion>,
        accepted: &AcceptedRoleStep,
        output: &RoleOutput,
        node: usize,
        mut next: PcRepairStep,
    ) -> Result<(), PalsError> {
        let terminal = self.owner.semantic.nodes[node].terminal.is_some();
        match next.phase {
            PcRepairPhase::Proposal => {
                next.proposal = next.prefix.clone();
                let line = self.publish_pc_repair_line_with_relations(
                    RecordKind::Proposal,
                    &next.proposal,
                    PcLineRelations {
                        parent: None,
                        supersedes: None,
                    },
                )?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .proposal = Some(line);
                if terminal {
                    return self.finish_repair_unknown(
                        next.cycle,
                        "Rules terminated before counter query",
                    );
                }
                let root_side = self.owner.semantic.nodes[self.root].position.side_to_move();
                next.divergences = (1..next.proposal.len())
                    .filter(|&ply| {
                        self.repair_node(&next.proposal[..ply])
                            .ok()
                            .is_some_and(|node| {
                                self.owner.semantic.nodes[node].position.side_to_move() != root_side
                            })
                    })
                    .collect();
                if next.divergences.is_empty() {
                    return self.finish_repair_unknown(next.cycle, "no legal opponent attack site");
                }
                next.prefix.clear();
                next.phase = PcRepairPhase::AttackRanking;
                self.push_repair_plan(
                    self.root,
                    next,
                    Some(PcPeerSource::freeze(input, accepted, output)?),
                )
            }
            PcRepairPhase::CounterTail => {
                next.counter = Some(next.prefix.clone());
                let parent = self
                    .repair_cycles
                    .as_ref()
                    .and_then(|cycles| cycles.active.get(&next.cycle))
                    .and_then(|facts| facts.proposal)
                    .ok_or(RoleError::InvalidOutput)?;
                let line = self.publish_pc_repair_line_with_relations(
                    RecordKind::Counterexample,
                    &next.prefix,
                    PcLineRelations {
                        parent: Some(parent),
                        supersedes: None,
                    },
                )?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .counter = Some(line);
                if terminal {
                    return self.finish_repair_unknown(
                        next.cycle,
                        "Rules ended before an accepted P Repair",
                    );
                }
                next.prefix.clear();
                next.divergences = vec![next.attack.ok_or(RoleError::InvalidOutput)?];
                next.phase = PcRepairPhase::VisibleCounterReview;
                self.push_repair_plan(self.root, next, None)
            }
            PcRepairPhase::Repair => {
                next.repaired = Some(next.prefix.clone());
                let facts = self
                    .repair_cycles
                    .as_ref()
                    .and_then(|cycles| cycles.active.get(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?;
                let parent = facts.counter.ok_or(RoleError::InvalidOutput)?;
                let previous = facts.previous_repair;
                let line = self.publish_pc_repair_line_with_relations(
                    RecordKind::Repair,
                    &next.prefix,
                    PcLineRelations {
                        parent: Some(parent),
                        supersedes: previous,
                    },
                )?;
                let fact = super::repair_witness::PcRepairAcceptedLine::capture(
                    input,
                    accepted,
                    output,
                    line.line,
                    line.observation,
                    line.revision,
                    RecordKind::Repair,
                    &self.owner.semantic.stores,
                )?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .repair = Some(Arc::new(fact));
                if terminal {
                    return self.finish_repair_unknown(
                        next.cycle,
                        "Repair Rules terminal has no matched comparison yet",
                    );
                }
                let counter = next.counter.as_ref().ok_or(RoleError::InvalidOutput)?;
                let root_side = self.owner.semantic.nodes[self.root].position.side_to_move();
                let changed = (next.attack.ok_or(RoleError::InvalidOutput)? + 1..next.prefix.len())
                    .find(|&ply| {
                        self.repair_node(&next.prefix[..ply])
                            .ok()
                            .is_some_and(|node| {
                                self.owner.semantic.nodes[node].position.side_to_move() == root_side
                            })
                            && counter.get(ply) != next.prefix.get(ply)
                    });
                let anchor = changed.and_then(|changed| {
                    (changed + 1..next.prefix.len()).find(|&ply| {
                        self.repair_node(&next.prefix[..ply])
                            .ok()
                            .is_some_and(|node| {
                                self.owner.semantic.nodes[node].position.side_to_move() != root_side
                            })
                    })
                });
                let Some(anchor) = anchor else {
                    return self.finish_repair_unknown(
                        next.cycle,
                        "no changed P move with a subsequent C turn",
                    );
                };
                next.excluded = next.prefix.get(anchor).copied();
                next.proposal = next
                    .repaired
                    .as_ref()
                    .ok_or(RoleError::InvalidOutput)?
                    .clone();
                next.prefix.truncate(anchor);
                next.phase = PcRepairPhase::RecheckStart;
                let node = self.repair_node(&next.prefix)?;
                self.push_repair_plan(
                    node,
                    next,
                    Some(PcPeerSource::freeze(input, accepted, output)?),
                )
            }
            PcRepairPhase::RecheckTail => {
                let facts = self
                    .repair_cycles
                    .as_ref()
                    .and_then(|cycles| cycles.active.get(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?;
                let repair = facts.repair.as_ref().ok_or(RoleError::InvalidOutput)?;
                let parent = PublishedPcLine {
                    line: repair.line(),
                    observation: repair.observation(),
                    revision: repair.revision(),
                    kind: repair.kind(),
                };
                let previous = facts.counter;
                let line = self.publish_pc_repair_line_with_relations(
                    RecordKind::Counterexample,
                    &next.prefix,
                    PcLineRelations {
                        parent: Some(parent),
                        supersedes: previous,
                    },
                )?;
                let fact = super::repair_witness::PcRepairAcceptedLine::capture(
                    input,
                    accepted,
                    output,
                    line.line,
                    line.observation,
                    line.revision,
                    RecordKind::Counterexample,
                    &self.owner.semantic.stores,
                )?;
                self.repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?
                    .recheck = Some(Arc::new(fact));
                if terminal {
                    return self.finish_repair_unknown(
                        next.cycle,
                        "C Rules terminal awaits a matched terminal proof pair",
                    );
                }
                next.counter = Some(next.prefix.clone());
                next.phase = PcRepairPhase::FreezePair;
                // Keep the complete, actually accepted C frontier before the
                // two Fresh questions filter duties to their own descendants.
                // This recipe has no selected View or native latent custody.
                let facts = self
                    .repair_cycles
                    .as_mut()
                    .and_then(|cycles| cycles.active.get_mut(&next.cycle))
                    .ok_or(RoleError::InvalidOutput)?;
                facts.recheck_publication = Some(line);
                facts.followup = Some(next.clone());
                self.push_repair_plan(node, next, None)
            }
            _ => Err(RoleError::InvalidOutput.into()),
        }
    }

    fn finish_repair_unknown(&mut self, id: u64, reason: &'static str) -> Result<(), PalsError> {
        let cycles = self
            .repair_cycles
            .as_mut()
            .ok_or(PalsError::InvalidConfig)?;
        let facts = cycles.active.get_mut(&id).ok_or(RoleError::InvalidOutput)?;
        if facts.target.is_none() {
            // There is no visible-counter label to mint, but earlier accepted
            // root/P/C heads are still real historical consumption. Preserve
            // their bounded progress instead of treating this cycle as absent.
            facts.stopped_reason = Some(reason);
            return Ok(());
        }
        if facts.target.is_some() {
            if cycles.witnesses.len() >= MAX_CYCLES {
                return Err(PalsError::Capacity);
            }
            cycles
                .witnesses
                .try_reserve(1)
                .map_err(|_| PalsError::Capacity)?;
        }
        let event = cycles.next_event;
        let next_event = event.checked_add(1).ok_or(PalsError::Capacity)?;
        let facts = cycles.active.remove(&id).ok_or(RoleError::InvalidOutput)?;
        if let Some(source) = facts.target {
            cycles.next_event = next_event;
            cycles
                .witnesses
                .push_back(super::repair_witness::PcDivergenceWitness::unresolved(
                    source,
                    facts.repair,
                    facts.recheck,
                    facts.repair_endpoint,
                    facts.counter_endpoint,
                    event,
                    reason,
                ));
        }
        Ok(())
    }

    /// Select both endpoints once, only when this ready recipe is actually
    /// admitted. The second input never follows a later public-record update.
    pub(super) fn materialize_repair_recipe(&mut self, plan: &PcPlan) -> Result<(), PalsError> {
        let step = plan.repair.as_ref().ok_or(RoleError::InvalidOutput)?;
        self.repair_control(step)?;
        if !step.is_recipe() {
            return Err(RoleError::InvalidOutput.into());
        }
        let lease = self.review_lease_admission()?;
        if lease
            .current
            .checked_add(2)
            .and_then(|n| n.checked_add(lease.frontier_replacement_reserve))
            .is_none_or(|n| n > lease.capacity)
        {
            return Err(StoreError::ReviewLeaseBackpressure {
                current: lease.current,
                capacity: lease.capacity,
                required_new: 2,
                replacement_reserve: lease.frontier_replacement_reserve,
            }
            .into());
        }
        if self
            .ready
            .len()
            .checked_add(1)
            .is_none_or(|n| n > MAX_PC_PENDING)
        {
            return Err(PalsError::Capacity);
        }
        self.ready.try_reserve(1).map_err(|_| PalsError::Capacity)?;
        let repair = step
            .repaired
            .as_ref()
            .ok_or(RoleError::InvalidOutput)?
            .clone();
        let counter = step
            .counter
            .as_ref()
            .ok_or(RoleError::InvalidOutput)?
            .clone();
        let repair_node = self.repair_node(&repair)?;
        let counter_node = self.repair_node(&counter)?;
        if self.owner.semantic.nodes[repair_node].terminal.is_some()
            || self.owner.semantic.nodes[counter_node].terminal.is_some()
        {
            return Err(RoleError::InvalidOutput.into());
        }
        let repair_legal = self.owner.semantic.nodes[repair_node]
            .position
            .legal_moves();
        let counter_legal = self.owner.semantic.nodes[counter_node]
            .position
            .legal_moves();
        let pair = self
            .owner
            .semantic
            .prepare_frozen_review_views(
                &self.owner.profile.sequence_config(),
                repair_node,
                RoleQuestion {
                    purpose: RoleQueryPurpose::ValueFresh,
                    prefix: &repair,
                    proposal: &repair,
                    refutation: None,
                    divergences: &[],
                },
                &repair_legal,
                counter_node,
                RoleQuestion {
                    purpose: RoleQueryPurpose::ValueFresh,
                    prefix: &counter,
                    proposal: &counter,
                    refutation: None,
                    divergences: &[],
                },
                &counter_legal,
            )?
            .ok_or(PalsError::InvalidConfig)?;
        let mut first = step.as_ref().clone();
        first.phase = PcRepairPhase::FreshRepair;
        first.prefix = repair.clone();
        first.proposal = repair;
        first.counter = None;
        first.divergences.clear();
        first.frozen = Some(pair.0);
        first.frozen_context = Some(self.owner.role_context(
            repair_node,
            RoleQuestion {
                purpose: RoleQueryPurpose::ValueFresh,
                prefix: &first.prefix,
                proposal: &first.proposal,
                refutation: None,
                divergences: &[],
            },
        )?);
        first
            .responsibilities
            .retain(|source| first.prefix.starts_with(source.prefix()));
        let mut second = step.as_ref().clone();
        second.phase = PcRepairPhase::FreshCounter;
        second.prefix = counter.clone();
        second.proposal = counter;
        second.counter = None;
        second.divergences.clear();
        second.frozen = Some(pair.1);
        second.frozen_context = Some(self.owner.role_context(
            counter_node,
            RoleQuestion {
                purpose: RoleQueryPurpose::ValueFresh,
                prefix: &second.prefix,
                proposal: &second.proposal,
                refutation: None,
                divergences: &[],
            },
        )?);
        second
            .responsibilities
            .retain(|source| second.prefix.starts_with(source.prefix()));
        self.ready.pop_front();
        self.push_repair_plan(repair_node, first, None)?;
        self.push_repair_plan(counter_node, second, None)
    }

    fn consume_repair_endpoint(
        &mut self,
        input: &FrameInput<ReviewView, PcPortQuestion>,
        accepted: &AcceptedRoleStep,
        output: &RoleOutput,
        physical: AdaptivePortRoleEvidence,
        step: &PcRepairStep,
    ) -> Result<(), PalsError> {
        let perspective = self.owner.semantic.nodes[self.root].position.side_to_move();
        let endpoint = super::repair_witness::PcAcceptedFreshEndpoint::capture(
            input,
            accepted,
            output,
            physical,
            &step.origin.model,
            perspective,
            &self.owner.semantic.stores,
        )?;
        self.commit_value(input, output)?;
        self.accept_frontier_endpoint(input, Some((accepted, output, physical)))?;
        let cycles = self
            .repair_cycles
            .as_mut()
            .ok_or(PalsError::InvalidConfig)?;
        let facts = cycles
            .active
            .get_mut(&step.cycle)
            .ok_or(RoleError::InvalidOutput)?;
        let slot = if step.phase == PcRepairPhase::FreshRepair {
            &mut facts.repair_endpoint
        } else {
            &mut facts.counter_endpoint
        };
        if slot.is_some() {
            return Err(RoleError::InvalidOutput.into());
        }
        *slot = Some(endpoint);
        if facts.repair_endpoint.is_none() || facts.counter_endpoint.is_none() {
            return Ok(());
        }
        if cycles.witnesses.len() >= MAX_CYCLES {
            return Err(PalsError::Capacity);
        }
        cycles
            .witnesses
            .try_reserve(1)
            .map_err(|_| PalsError::Capacity)?;
        let event = cycles.next_event;
        let next = event.checked_add(1).ok_or(PalsError::Capacity)?;
        let facts = cycles
            .active
            .get(&step.cycle)
            .ok_or(RoleError::InvalidOutput)?;
        let witness = super::repair_witness::PcDivergenceWitness::from_frozen_pair(
            Arc::clone(facts.target.as_ref().ok_or(RoleError::InvalidOutput)?),
            Arc::clone(facts.repair.as_ref().ok_or(RoleError::InvalidOutput)?),
            Arc::clone(facts.recheck.as_ref().ok_or(RoleError::InvalidOutput)?),
            facts
                .repair_endpoint
                .as_ref()
                .ok_or(RoleError::InvalidOutput)?
                .clone(),
            facts
                .counter_endpoint
                .as_ref()
                .ok_or(RoleError::InvalidOutput)?
                .clone(),
            event,
        )?;
        // A completed actual C frontier remains eligible for another bounded
        // Repair even when the conditional WDL comparison is unknown. Prepare
        // all admission capacity while the original completed facts remain.
        let followup = self.prepare_completed_repair_followup(step.cycle)?;
        let cycles = self
            .repair_cycles
            .as_mut()
            .ok_or(PalsError::InvalidConfig)?;
        cycles.active.remove(&step.cycle);
        cycles.next_event = next;
        cycles.witnesses.push_back(witness);
        if let Some(followup) = followup {
            self.enqueue_completed_repair_followup(followup)?;
        }
        Ok(())
    }
}
